/bin/bash -lc "python3 - <<'PY'
import json, importlib.util
from pathlib import Path

slug = 'what_is_the_registrants_exact_name'
rules_dir = Path('/mnt/data/LSF/rules/financebench/grid/random/agent_codex_gpt54') / slug
labels = json.loads(Path('data/financebench/sample/single_cluster/random/sample_doc_labels.json').read_text())
doc_names = [k.replace('.pdf','') for k in labels]
proc_dir = Path('data/financebench/processing')

rules = {}
for py in sorted(rules_dir.glob('rule_*.py')):
    spec = importlib.util.spec_from_file_location(py.stem, py)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    fn = getattr(mod, py.stem)
    rules[py.stem] = fn

hits = {r: [] for r in rules}
for dn in doc_names:
    doc = json.loads((proc_dir / f'{dn}_reconstructed.json').read_text())
    for r, fn in rules.items():
        try:
            out = fn(doc)
        except Exception:
            out = []
        if out:
            hits[r].append(dn)

print(json.dumps({
    'n_docs': len(doc_names),
    'per_rule_doc_hits': {r: {'count': len(v), 'docs': v} for r, v in hits.items()},
}, indent=2))
PY"

